public class FileRevisionOracle {
 public static String observe() {
  List<Object> rows=new List<Object>();
  for(String path:new List<String>{'specimen','specimen.txt'}) {
   ContentVersion v=new ContentVersion(Title='Owned specimen',PathOnClient=path,VersionData=Blob.valueOf('owned bytes'),IsMajorVersion=false);insert v;
   ContentVersion q=[SELECT Id,UploadToken__c,ContentDocument.Title,ContentDocumentId,VersionData FROM ContentVersion WHERE Id=:v.Id];
   ContentVersion extensionView=[SELECT FileExtension FROM ContentVersion WHERE Id=:v.Id];
   Map<String,Object> r=new Map<String,Object>{'path'=>path,'extension'=>extensionView.FileExtension,'extensionNull'=>extensionView.FileExtension==null};
   try{q.UploadToken__c='queried';update q;r.put('queried','accepted');}catch(Exception e){r.put('queriedType',e.getTypeName());r.put('queriedMessage',e.getMessage());}
   try{update new ContentVersion(Id=v.Id,UploadToken__c='sparse');r.put('sparse','accepted');}catch(Exception e){r.put('sparseType',e.getTypeName());r.put('sparseMessage',e.getMessage());}
   try{ContentVersion denied=new ContentVersion(Id=v.Id);denied.put('FileExtension','changed');update denied;r.put('explicit','accepted');}catch(Exception e){r.put('explicitType',e.getTypeName());r.put('explicitMessage',e.getMessage());}
   try{ContentDocument doc=[SELECT Id,Title FROM ContentDocument WHERE Id=:q.ContentDocumentId];doc.Title='Updated specimen';update doc;r.put('documentUpdate','accepted');}catch(Exception e){r.put('documentType',e.getTypeName());r.put('documentMessage',e.getMessage());}
   try{ContentVersion replacement=new ContentVersion(ContentDocumentId=q.ContentDocumentId,Title='Replacement',PathOnClient='replacement',VersionData=Blob.valueOf('new owned bytes'));insert replacement;ContentDocument doc=[SELECT FileExtension FROM ContentDocument WHERE Id=:q.ContentDocumentId];r.put('replacementExtension',doc.FileExtension);r.put('replacementExtensionNull',doc.FileExtension==null);}catch(Exception e){r.put('replacementType',e.getTypeName());r.put('replacementMessage',e.getMessage());}
   rows.add(r);
  }
  return JSON.serialize(rows);
 }
}
